 m=n//2; g=[[0]*n for _ in range(n)]
 for r in range(m+1):
  g[r][m-r]=g[r][m+r]=2
 for r in range(3,n):
  for c in range(max(0,m-r),min(n-1,m+r)+1):
   if (c-r-m)%4==0 and g[r][c]==0: g[r][c]=1
 return g
